values ('RD-A1-042', 'A1', 'chat', 'administration', 7, 'Забула пароль', 'Zaboravljena lozinka',
        'Daša: Marko, ne mogu se prijaviti u e-Građane. Zaboravila sam lozinku!
Marko: Klikni na «Zaboravili ste lozinku?» i unesi adresu e-pošte.
Daša: Imam kod za potvrdu. Što sada?
Marko: Unesi kod i novu lozinku. Ne govori lozinku drugima!
Daša: Hvala, sve radi 🙂',
        'Даша: Марку, я не можу увійти в e-Građani. Я забула пароль!
Марко: Натисни «Забули пароль?» і введи адресу електронної пошти.
Даша: У мене є код підтвердження. Що тепер?
Марко: Введи код і новий пароль. Не кажи пароль іншим!
Даша: Дякую, усе працює 🙂',
        '[{"form": "daša", "lemma": "Daša", "ua": "Даша (ім’я)", "lesson": false, "pos": "ім’я (жіноче)"}, {"form": "marko", "lemma": "Marko", "ua": "Марко (ім’я)", "lesson": false, "pos": "ім’я (чоловіче)"}, {"form": "ne", "lemma": "ne", "ua": "ні", "lesson": true, "pos": "частка"}, {"form": "mogu", "lemma": "moći", "ua": "могти", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: вони"}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false, "pos": "зворотний займенник «себе / -ся» (коротка форма; стоїть на другому місці в реченні)"}, {"form": "prijaviti", "lemma": "prijaviti", "ua": "зареєструвати; повідомити", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "e-građane", "lemma": "e-Građani", "ua": "е-Громадяни (державний портал Хорватії)", "lesson": true, "pos": "державний онлайн-сервіс (назва; множина)", "gram": "знахідний відмінок (кого? що?), множина. «u e-Građane» — куди? (сервіс e-Građani)"}, {"form": "zaboravila", "lemma": "zaboraviti", "ua": "забути", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "минулий час (форма на -l): ж. р., однина"}, {"form": "sam", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: я. Коротка форма; також допоміжне в минулому часі («došla sam» — я приїхала)"}, {"form": "lozinku", "lemma": "lozinka", "ua": "пароль", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "klikni", "lemma": "kliknuti", "ua": "клікнути, клацнути (мишкою)", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ти (зроби!)"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "zaboravili", "lemma": "zaboraviti", "ua": "забути", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "минулий час (форма на -l): ч. р., множина. «Zaboravili ste» — ви забули (ввічливо)"}, {"form": "ste", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: ви (і ввічливе «Ви»)"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "unesi", "lemma": "unijeti", "ua": "ввести (дані); внести", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ти (зроби!)"}, {"form": "adresu", "lemma": "adresa", "ua": "адреса", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "e-pošte", "lemma": "e-pošta", "ua": "електронна пошта", "lesson": true, "pos": "іменник, жіночий рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "imam", "lemma": "imati", "ua": "мати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: я"}, {"form": "kod", "lemma": "kod", "ua": "у; біля; в (когось)", "lesson": false, "pos": "прийменник + родовий відмінок («kod kuće» — вдома, «kod liječnika» — у лікаря)"}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false, "pos": "прийменник: + знахідний — для, за («za strance» — для іноземців)"}, {"form": "potvrdu", "lemma": "potvrda", "ua": "довідка / підтвердження", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "što", "lemma": "što", "ua": "що", "lesson": true, "pos": "займенник «що»; як сполучник — «що» («Hvala što …»)"}, {"form": "sada", "lemma": "sada", "ua": "зараз", "lesson": true, "pos": "прислівник"}, {"form": "novu", "lemma": "nov", "ua": "новий", "lesson": true, "pos": "прикметник", "gram": "знахідн