values ('RD-A1-044', 'A1', 'instruction', 'administration', 7, 'Як увійти в e-Građani', 'Prijava u e-Građane',
        'Kako se prijaviti u e-Građane?
1. Otvorite web-stranicu e-Građani.
2. Kliknite na «Prijava».
3. Odaberite osobnu iskaznicu ili mobilni token.
4. Unesite PIN ili kod za potvrdu.
5. Sada možete vidjeti svoje dokumente i ispuniti obrazac na internetu.',
        'Як увійти в e-Građani?
1. Відкрийте сайт e-Građani.
2. Натисніть «Вхід».
3. Виберіть особисте посвідчення або мобільний токен.
4. Введіть PIN або код підтвердження.
5. Тепер ви можете бачити свої документи й заповнити форму в інтернеті.',
        '[{"form": "kako", "lemma": "kako", "ua": "як", "lesson": true, "pos": "питальний прислівник «як»"}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false, "pos": "зворотний займенник «себе / -ся» (коротка форма; стоїть на другому місці в реченні)"}, {"form": "prijaviti", "lemma": "prijaviti", "ua": "зареєструвати; повідомити", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "e-građane", "lemma": "e-Građani", "ua": "е-Громадяни (державний портал Хорватії)", "lesson": true, "pos": "державний онлайн-сервіс (назва; множина)", "gram": "знахідний відмінок (кого? що?), множина. «u e-Građane» — куди? (сервіс e-Građani)"}, {"form": "otvorite", "lemma": "otvoriti", "ua": "відчинити / відкрити", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "web-stranicu", "lemma": "web-stranica", "ua": "вебсайт", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "e-građani", "lemma": "e-Građani", "ua": "е-Громадяни (державний портал Хорватії)", "lesson": true, "pos": "державний онлайн-сервіс (назва; множина)"}, {"form": "kliknite", "lemma": "kliknuti", "ua": "клікнути, клацнути (мишкою)", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "prijava", "lemma": "prijava", "ua": "заявка; реєстрація", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "odaberite", "lemma": "odabrati", "ua": "вибрати", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "osobnu", "lemma": "osobna iskaznica", "ua": "посвідчення особи", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина. Частина виразу «osobna iskaznica»"}, {"form": "iskaznicu", "lemma": "osobna iskaznica", "ua": "посвідчення особи", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина. Частина виразу «osobna iskaznica»"}, {"form": "ili", "lemma": "ili", "ua": "або; чи", "lesson": true, "pos": "сполучник"}, {"form": "mobilni", "lemma": "mobilni token", "ua": "мобільний токен", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «mobilni token»"}, {"form": "token", "lemma": "mobilni token", "ua": "мобільний токен", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «mobilni token»"}, {"form": "unesite", "lemma": "unijeti", "ua": "ввести (дані); внести", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "pin", "lemma": "PIN", "ua": "PIN-код", "lesson": true, "pos": "абревіатура (особистий код)"}, {"form": "kod", "lemma": "kod", "ua": "у; біля; в (когось)", "lesson": false, "pos": "прийменник + родовий відмінок («kod kuće» — вдома, «kod liječnika» — у лікаря)"}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false, "pos": "прийменник: + знахідний — для, за («za strance» — для іноземців)"}, {"form": "potvrdu", "lemma": "potvrda", "ua": "довідка / підтвердження", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "sada", "lemma": "sada", "ua": "зараз", "lesson": true, "pos": "прислівник"}, {"form": "možete", "lemma": "moći", "ua": "могти", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: ви (і ввічливе «Ви»)"}, {"form": "vidjeti", "lemma": "vidjeti", "ua": "бачити", "lesson": true, "pos": "дієслово, доконаний і недоконаний вид"}, {"form": "svoje", "lemma": "svoj", "ua": "свій", "lesson": true, "pos": "присвійний займенник «свій»", "gram": "знахідний відмінок (кого? що?), множина, ч. р."}, {"form": "dokumente", "lemma": "dokument", "ua": "документ", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "знахідний відмінок (кого? що?), множина"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "ispuniti", "lemma": "ispuniti", "ua": "заповнити", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)"}, {"form": "obrazac", "lemma": "obrazac", "ua": "бланк / анкета", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "internetu", "lemma": "internet", "ua": "інтернет", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}]'::jsonb,
        '[{"question_ua": "Що треба зробити спочатку?", "options": ["Відкрити сайт e-Građani", "Ввести PIN", "Заповнити форму"], "answer": "Відкрити сайт e-Građani"}, {"question_ua": "Що можна вибрати для входу?", "options": ["Посвідчення або мобільний токен", "Паспорт або квиток", "Банківську картку"], "answer": "Посвідчення або мобільний токен"}, {"question_ua": "Що можна робити після входу?", "options": ["Бачити документи й заповнити форму", "Купувати квитки", "Дзвонити лікареві"], "answer": "Бачити документи й заповнити форму"}]'::jsonb, 33, 1.000, 44, 'PUBLISHED', 'claude_reading_a1_v3')
