values ('RD-A1-045', 'A1', 'story', 'small_talk', 11, 'Недільний обід у бабусі', 'Nedjeljni ručak kod bake',
        'Svake nedjelje Daša i Marko idu na nedjeljni ručak kod bake u Split. Baka kuha pašticadu ili peku. Prije ručka svi nazdrave: «Živjeli!» Poslije ručka piju kavu i jedu kremšnitu. Baka uvijek kaže: «Jedite, djeco, ima još!»',
        'Щонеділі Даша й Марко їдуть на недільний обід до бабусі в Спліт. Бабуся готує паштіцаду або пеку. Перед обідом усі піднімають келихи: «Будьмо!» Після обіду п’ють каву і їдять кремшніту. Бабуся завжди каже: «Їжте, діти, є ще!»',
        '[{"form": "svake", "lemma": "svaki", "ua": "кожен", "lesson": true, "pos": "займенник «кожен»", "gram": "родовий відмінок (кого? чого?), однина, ж. р."}, {"form": "nedjelje", "lemma": "nedjelja", "ua": "неділя", "lesson": true, "pos": "іменник, жіночий рід", "gram": "родовий відмінок (кого? чого?), однина. «do nedjelje» — до неділі"}, {"form": "daša", "lemma": "Daša", "ua": "Даша (ім’я)", "lesson": false, "pos": "ім’я (жіноче)"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "marko", "lemma": "Marko", "ua": "Марко (ім’я)", "lesson": false, "pos": "ім’я (чоловіче)"}, {"form": "idu", "lemma": "ići", "ua": "іти, їхати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: вони"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "nedjeljni", "lemma": "nedjeljni ručak", "ua": "недільний обід", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина. Частина виразу «nedjeljni ručak»"}, {"form": "ručak", "lemma": "ručak", "ua": "обід", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "kod", "lemma": "kod", "ua": "у; біля; в (когось)", "lesson": false, "pos": "прийменник + родовий відмінок («kod kuće» — вдома, «kod liječnika» — у лікаря)"}, {"form": "bake", "lemma": "baka", "ua": "бабуся", "lesson": true, "pos": "іменник, жіночий рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "split", "lemma": "Split", "ua": "Спліт (місто)", "lesson": false, "pos": "назва місця"}, {"form": "baka", "lemma": "baka", "ua": "бабуся", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "kuha", "lemma": "kuhati", "ua": "варити / готувати їжу", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: він / вона / воно"}, {"form": "pašticadu", "lemma": "pašticada", "ua": "паштицада (далматинська тушкована яловичина)", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "ili", "lemma": "ili", "ua": "або; чи", "lesson": true, "pos": "сполучник"}, {"form": "peku", "lemma": "peka", "ua": "пека (страва під залізною кришкою на жару)", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "prije", "lemma": "prije", "ua": "до; перед; раніше", "lesson": true, "pos": "прийменник + родовий («prije osam sati»); прислівник «раніше»"}, {"form": "ručka", "lemma": "ručak", "ua": "обід", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "svi", "lemma": "sav", "ua": "весь; усі", "lesson": false, "pos": "займенник «весь, усі»", "gram": "називний відмінок (хто? що?), множина, ч. р."}, {"form": "nazdrave", "lemma": "nazdraviti", "ua": "виголосити тост, цокнутися", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "теперішній час: вони"}, {"form": "živjeli", "lemma": "živjeli", "ua": "будьмо! (тост)", "lesson": true, "pos": "вигук"}, {"form": "poslije", "lemma": "poslije", "ua": "після", "lesson": true, "pos": "прийменник + родовий («poslije posla»); прислівник «потім»"}, {"form": "piju", "lemma": "piti", "ua": "пити", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: вони"}, {"form": "kavu", "lemma": "kava", "ua": "кава", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "jedu", "lemma": "jesti", "ua": "їсти", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: вони"}, {"form": "kremšnitu", "lemma": "kremšnita", "ua": "кремшніта (тістечко з кремом)", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "uvijek", "lemma": "uvijek", "ua": "завжди", "lesson": true, "pos": "прислівник"}, {"form": "kaže", "lemma": "reći", "ua": "сказати (kaže — каже)", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "теперішній час: він / вона / воно. Теперішній час від reći / kazati: kažem, kažeš, kaže"}, {"form": "jedite", "lemma": "jesti", "ua": "їсти", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "djeco", "lemma": "djeca", "ua": "діти", "lesson": true, "pos": "іменник «діти» (множина до dijete); прикметник при ньому — як при ж. р. однини: «moja djeca»", "gram": "кличний відмінок (звертання), множина. Кличний від djeca: «Djeco!» — діти!"}, {"form": "ima", "lemma": "imati", "ua": "мати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: він / вона / воно"}, {"form": "još", "lemma": "još", "ua": "ще («još uvijek» — досі)", "lesson": true, "pos": "прислівник «ще»; «još uvijek» — досі"}]'::jsonb,
        '[{"question_ua": "Куди Даша й Марко їдуть щонеділі?", "options": ["До бабусі в Спліт", "До Загреба", "У ресторан"], "answer": "До бабусі в Спліт"}, {"question_ua": "Що кажуть перед обідом?", "options": ["«Živjeli!»", "«Dobar dan!»", "«Hvala!»"], "answer": "«Živjeli!»"}, {"question_ua": "Що вони їдять після обіду?", "options": ["Кремшніту", "Паштіцаду", "Піцу"], "answer": "Кремшніту"}]'::jsonb, 37, 1.000, 45, 'PUBLISHED', 'claude_reading_a1_v3')
