values ('RD-A1-046', 'A1', 'notice', 'small_talk', 11, 'Різдво в місті', 'Božić u gradu',
        'BOŽIĆ U GRADU
24. prosinca u 23 sata: polnoćka u katedrali.
25. prosinca: Božić, neradni dan – trgovine ne rade.
26. prosinca: Sveti Stjepan, također neradni dan.
Na trgu je božićno drvce s lampicama, a djeca mogu vidjeti jaslice.',
        'РІЗДВО В МІСТІ
24 грудня о 23:00: опівнічна меса в соборі.
25 грудня: Різдво, вихідний день — магазини не працюють.
26 грудня: День святого Степана, теж вихідний.
На площі — різдвяна ялинка з вогниками, а діти можуть побачити вертеп.',
        '[{"form": "božić", "lemma": "Božić", "ua": "Різдво", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "gradu", "lemma": "grad", "ua": "місто", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "prosinca", "lemma": "prosinac", "ua": "грудень", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "родовий відмінок (кого? чого?), однина. У даті: «24. prosinca» — 24 грудня"}, {"form": "sata", "lemma": "sat", "ua": "годинник / година", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "родовий відмінок (кого? чого?), однина. Після 2, 3, 4 і «pola»: «dva sata», «pola sata»"}, {"form": "polnoćka", "lemma": "polnoćka", "ua": "опівнічна різдвяна меса", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "katedrali", "lemma": "katedrala", "ua": "собор", "lesson": true, "pos": "іменник, жіночий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "neradni", "lemma": "neradni dan", "ua": "вихідний, неробочий день", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «neradni dan»"}, {"form": "dan", "lemma": "dan", "ua": "день", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "trgovine", "lemma": "trgovina", "ua": "магазин / крамниця", "lesson": true, "pos": "іменник, жіночий рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "ne", "lemma": "ne", "ua": "ні", "lesson": true, "pos": "частка"}, {"form": "rade", "lemma": "raditi", "ua": "працювати, робити", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: вони"}, {"form": "sveti", "lemma": "Sveti Stjepan", "ua": "день святого Стефана (26 грудня)", "lesson": true, "pos": "сталий вираз", "gram": "частина назви свята «Sveti Stjepan»"}, {"form": "stjepan", "lemma": "Sveti Stjepan", "ua": "день святого Стефана (26 грудня)", "lesson": true, "pos": "сталий вираз", "gram": "частина назви свята «Sveti Stjepan»"}, {"form": "također", "lemma": "također", "ua": "також", "lesson": true, "pos": "прислівник"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "trgu", "lemma": "trg", "ua": "площа", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: він / вона / воно. Коротка форма"}, {"form": "božićno", "lemma": "božićno drvce", "ua": "ялинка", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «božićno drvce»"}, {"form": "drvce", "lemma": "božićno drvce", "ua": "ялинка", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «božićno drvce»"}, {"form": "s", "lemma": "s", "ua": "з (разом із)", "lesson": false, "pos": "прийменник «з»: + орудний — разом із («s obitelji»); + родовий — звідки («s Hvara», «s posla»)"}, {"form": "lampicama", "lemma": "lampice", "ua": "гірлянда, вогники", "lesson": true, "pos": "іменник, ж. р., лише множина", "gram": "орудний відмінок (ким? чим?), множина"}, {"form": "a", "lemma": "a", "ua": "а; і", "lesson": false, "pos": "сполучник"}, {"form": "djeca", "lemma": "djeca", "ua": "діти", "lesson": true, "pos": "іменник «діти» (множина до dijete); прикметник при ньому — як при ж. р. однини: «moja djeca»"}, {"form": "mogu", "lemma": "moći", "ua": "могти", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: вони"}, {"form": "vidjeti", "lemma": "vidjeti", "ua": "бачити", "lesson": true, "pos": "дієслово, доконаний і недоконаний вид"}, {"form": "jaslice", "lemma": "jaslice", "ua": "вертеп (різдвяна сцена з яслами)", "lesson": true, "pos": "іменник, ж. р., лише множина"}]'::jsonb,
        '[{"question_ua": "Де буде опівнічна меса?", "options": ["У соборі", "На площі", "У школі"], "answer": "У соборі"}, {"question_ua": "Що 25 грудня з магазинами?", "options": ["Вони не працюють", "Вони працюють до 23:00", "Там знижки"], "answer": "Вони не працюють"}, {"question_ua": "Що можуть побачити діти на площі?", "options": ["Вертеп", "Концерт", "Кіно"], "answer": "Вертеп"}]'::jsonb, 34, 1.000, 46, 'PUBLISHED', 'claude_reading_a1_v3')
on conflict (code) do nothing;
insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-047', 'A1', 'article', 'small_talk', 11, 'Хорватські звичаї: кава й гості', 'Hrvatski običaji: kava i gosti',
        'U Hrvatskoj ljudi često idu na kavu. Kava nije samo kava – to je vrijeme za prijatelje. Kad idete u goste, donesite nešto malo, na primjer kolač. U puno kuća gosti se izuju. Domaćica uvijek nudi jelo i piće, jer su Hrvati vrlo gostoljubivi.',
        'У Хорватії люди часто ходять на каву. Кава — це не просто кава, це час для друзів. Коли йдете в гості, принесіть щось невелике, наприклад тістечко. У багатьох домах гості знімають взуття. Господиня завжди пропонує їжу й напої, бо хорвати дуже гостинні.',
        '[{"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "hrvatskoj", "lemma": "Hrvatska", "ua": "Хорватія", "lesson": true, "pos": "назва місця", "gram": "місцевий відмінок (де? про кого? про що?), однина. «u Hrvatskoj» — де? (місцевий)"}, {"form": "ljudi", "lemma": "ljudi", "ua": "люди", "lesson": true, "pos": "іменник «люди» (множина до čovjek)"}, {"form": "često", "lemma": "često", "ua": "часто", "lesson": true, "pos": "прислівник"}, {"form": "idu", "lemma": "ići", "ua": "іти, їхати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: вони"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "kavu", "lemma": "kava", "ua": "кава", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "kava", "lemma": "kava", "ua": "кава", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "nije", "lemma": "nije", "ua": "не є; немає (заперечення biti)", "lesson": false, "pos": "заперечна форма дієслова biti: «не є» (nisam, nisi, nije, nismo, niste, nisu)"}, {"form": "samo", "lemma": "samo", "ua": "тільки; лише", "lesson": true, "pos": "прислівник «тільки»"}, {"form": "to", "lemma": "to", "ua": "це; те", "lesson": false, "pos": "вказівний займенник «це, те» (с. р.)"}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: він / вона / воно. Коротка форма"}, {"form": "vrijeme", "lemma": "vrijeme", "ua": "погода / час", "lesson": true, "pos": "іменник, середній рід"}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false, "pos": "прийменник: + знахідний — для, за («za strance» — для іноземців)"}, {"form": "prijatelje", "lemma": "prijatelj", "ua": "друг", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "знахідний відмінок (кого? що?), множина"}, {"form": "kad", "lemma": "kada", "ua": "коли (також kad)", "lesson": true, "pos": "прислівник «коли» (коротко — kad); також сполучник", "gram": "коротка форма від kada"}, {"form": "idete", "lemma": "ići", "ua": "іти, їхати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: ви (і ввічливе «Ви»)"}, {"form": "goste", "lemma": "gost", "ua": "гість / відвідувач", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "знахідний відмінок (кого? що?), множина. «ići u goste» — іти в гості"}, {"form": "donesite", "lemma": "donijeti", "ua": "принести", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "nešto", "lemma": "nešto", "ua": "щось", "lesson": true, "pos": "займенник «щось»"}, {"form": "malo", "lemma": "malo", "ua": "мало / трохи", "lesson": true, "pos": "прислівник «мало, трохи» + родовий («malo soli»)"}, {"form": "primjer", "lemma": "primjer", "ua": "приклад («na primjer» — наприклад)", "lesson": false, "pos": "іменник, чоловічий рід"}, {"form": "kolač", "lemma": "kolač", "ua": "тістечко / пиріг", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "puno", "lemma": "puno", "ua": "багато", "lesson": true, "pos": "прислівник «багато» + родовий («puno turista»)"}, {"form": "kuća", "lemma": "kuća", "ua": "будинок; дім", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "gosti", "lemma": "gost", "ua": "гість / відвідувач", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "називний відмінок (хто? що?), множина"}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false, "pos": "зворотний займенник «себе / -ся» (коротка форма; стоїть на другому місці в реченні)"}, {"form": "izuju", "lemma": "izuti se", "ua": "роззутися", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "теперішній час: вони"}, {"form": "domaćica", "lemma": "domaćica", "ua": "господиня", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "uvijek", "lemma": "uvijek", "ua": "завжди", "lesson": true, "pos": "прислівник"}, {"form": "nudi", "lemma": "nuditi", "ua": "пропонувати", "lesson": false, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: він / вона / воно"}, {"form": "jelo", "lemma": "jelo", "ua": "страва", "lesson": true, "pos": "іменник, середній рід"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "piće", "lemma": "piće", "ua": "напій", "lesson": true, "pos": "іменник, середній рід"}, {"form": "jer", "lemma": "jer", "ua": "бо; тому що", "lesson": true, "pos": "сполучник"}, {"form": "su", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: вони"}, {"form": "hrvati", "lemma": "Hrvat", "ua": "хорват", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "називний відмінок (хто? що?), множина"}, {"form": "vrlo", "lemma": "vrlo", "ua": "дуже", "lesson": true, "pos": "прислівник"}, {"form": "gostoljubivi", "lemma": "gostoljubiv", "ua": "гостинний", "lesson": true, "pos": "прикметник", "gram": "називний відмінок (хто? що?), множина, ч. р."}]'::jsonb,
        '[{"question_ua": "Що означає «піти на каву»?", "options": ["Час для друзів", "Швидкий сніданок", "Робочу зустріч"], "answer": "Час для друзів"}, {"question_ua": "Що варто принести в гості?", "options": ["Щось невелике, наприклад тістечко", "Нічого", "Дорогий подарунок"], "answer": "Щось невелике, наприклад тістечко"}, {"question_ua": "Що роблять гості в багатьох домах?", "options": ["Знімають взуття", "Готують обід", "Приносять вино"], "answer": "Знімають взуття"}]'::jsonb, 43, 0.953, 47, 'PUBLISHED', 'claude_reading_a1_v3')
on conflict (code) do nothing;
insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-048', 'A1', 'message', 'travel', 11, 'Листівка з Дубровника', 'Razglednica iz Dubrovnika',
        'Draga Ivana,
pozdrav iz Dubrovnika! Danas šetamo po zidinama i gledamo tvrđavu i katedralu. Stari grad je jako lijep, ima puno uličica i kamenih kuća. Navečer jedemo crni rižot. Sutra idemo u samostan.
Pozdrav, Daša',
        'Дорога Івано,
привіт із Дубровника! Сьогодні ми гуляємо мурами й дивимося на фортецю та собор. Старе місто дуже гарне, у ньому багато вуличок і кам’яних будинків. Увечері ми їмо чорне різото. Завтра йдемо в монастир.
Обіймаю, Даша',
        '[{"form": "draga", "lemma": "drag", "ua": "дорогий; милий, приємний", "lesson": true, "pos": "прикметник", "gram": "називний відмінок (хто? що?), однина, ж. р. Звертання в листі"}, {"form": "ivana", "lemma": "Ivana", "ua": "Івана (ім’я)", "lesson": false, "pos": "ім’я (жіноче)"}, {"form": "pozdrav", "lemma": "pozdrav", "ua": "привіт; вітання", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "iz", "lemma": "iz", "ua": "з (звідки)", "lesson": true, "pos": "прийменник + родовий відмінок"}, {"form": "dubrovnika", "lemma": "Dubrovnik", "ua": "Дубровник (місто)", "lesson": false, "pos": "назва місця", "gram": "родовий відмінок (кого? чого?), однина. «iz Dubrovnika» — з Дубровника"}, {"form": "danas", "lemma": "danas", "ua": "сьогодні", "lesson": true, "pos": "прислівник"}, {"form": "šetamo", "lemma": "šetati", "ua": "прогулюватися / гуляти", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: ми"}, {"form": "po", "lemma": "po", "ua": "по; за (чимось)", "lesson": false, "pos": "прийменник: + знахідний — по що? («po voće» — по фрукти), + місцевий — де? («po stazama» — по стежках)"}, {"form": "zidinama", "lemma": "zidine", "ua": "міські мури", "lesson": true, "pos": "іменник «мури», ж. р., лише множина", "gram": "місцевий відмінок (де? про кого? про що?), множина"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "gledamo", "lemma": "gledati", "ua": "дивитися", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: ми"}, {"form": "tvrđavu", "lemma": "tvrđava", "ua": "фортеця", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "katedralu", "lemma": "katedrala", "ua": "собор", "lesson": true, "pos": "іменник, жіночий рід", "gram": "знахідний відмінок (кого? що?), однина"}, {"form": "stari", "lemma": "star", "ua": "старий", "lesson": true, "pos": "прикметник", "gram": "називний відмінок (х