insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-049', 'A1', 'notice', 'basics', 12, 'Оголошення в садку', 'Obavijest u vrtiću',
        'OBAVIJEST RODITELJIMA
U ponedjeljak u 17 sati je roditeljski sastanak u vrtiću.
Donesite rezervnu odjeću za dijete i kutiju za užinu.
Popodnevni odmor je od 13 do 14:30.
Djecu možete pokupiti do 17 sati.
Odgojiteljica Ana',
        'ОГОЛОШЕННЯ ДЛЯ БАТЬКІВ
У понеділок о 17:00 — батьківські збори в садку.
Принесіть запасний одяг для дитини й коробку для перекусу.
Денний сон — з 13:00 до 14:30.
Дітей можна забрати до 17:00.
Вихователька Ана',
        '[{"form": "obavijest", "lemma": "obavijest", "ua": "оголошення; повідомлення", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "roditeljima", "lemma": "roditelji", "ua": "батьки", "lesson": true, "pos": "іменник «батьки» (множина від roditelj), ч. р.", "gram": "давальний відмінок (кому? чому?), множина"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "ponedjeljak", "lemma": "ponedjeljak", "ua": "понеділок", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "sati", "lemma": "sat", "ua": "годинник / година", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "родовий відмінок (кого? чого?), множина. Після 5 і більше: «osam sati»"}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": true, "pos": "дієслово «бути» (недоконаний вид); короткі форми sam, si, je, smo, ste, su", "gram": "теперішній час: він / вона / воно. Коротка форма"}, {"form": "roditeljski", "lemma": "roditeljski sastanak", "ua": "батьківські збори", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «roditeljski sastanak»"}, {"form": "sastanak", "lemma": "roditeljski sastanak", "ua": "батьківські збори", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «roditeljski sastanak»"}, {"form": "vrtiću", "lemma": "vrtić", "ua": "дитячий садок", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "donesite", "lemma": "donijeti", "ua": "принести", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "rezervnu", "lemma": "rezervna odjeća", "ua": "змінний одяг", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина. Частина виразу «rezervna odjeća»"}, {"form": "odjeću", "lemma": "rezervna odjeća", "ua": "змінний одяг", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина. Частина виразу «rezervna odjeća»"}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false, "pos": "прийменник: + знахідний — для, за («za strance» — для іноземців)"}, {"form": "dijete", "lemma": "dijete", "ua": "дитина", "lesson": true, "pos": "іменник, с. р. «дитина» (множина — djeca)"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "kutiju", "lemma": "kutija za užinu", "ua": "ланчбокс, коробка для перекусу", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина. Частина виразу «kutija za užinu»"}, {"form": "užinu", "lemma": "kutija za užinu", "ua": "ланчбокс, коробка для перекусу", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), однина. Частина виразу «kutija za užinu»"}, {"form": "popodnevni", "lemma": "popodnevni odmor", "ua": "денний сон (у садочку)", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «popodnevni odmor»"}, {"form": "odmor", "lemma": "popodnevni odmor", "ua": "денний сон (у садочку)", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «popodnevni odmor»"}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false, "pos": "прийменник + родовий відмінок"}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false, "pos": "прийменник + родовий відмінок"}, {"form": "djecu", "lemma": "djeca", "ua": "діти", "lesson": true, "pos": "іменник «діти» (множина до dijete); прикметник при ньому — як при ж. р. однини: «moja djeca»", "gram": "знахідний відмінок (кого? що?), однина. «za djecu» — для дітей (djeca відмінюється як ж. р. однини)"}, {"form": "možete", "lemma": "moći", "ua": "могти", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: ви (і ввічливе «Ви»)"}, {"form": "pokupiti", "lemma": "pokupiti", "ua": "забрати (дитину, речі)", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)"}, {"form": "odgojiteljica", "lemma": "odgojiteljica", "ua": "вихователька", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "ana", "lemma": "Ana", "ua": "Ана (ім’я)", "lesson": false, "pos": "ім’я (жіноче)"}]'::jsonb,
        '[{"question_ua": "Коли батьківські збори?", "options": ["У понеділок о 17:00", "У п’ятницю о 13:00", "У неділю"], "answer": "У понеділок о 17:00"}, {"question_ua": "Що треба принести?", "options": ["Запасний одяг і коробку для перекусу", "Книжки", "Гроші"], "answer": "Запасний одяг і коробку для перекусу"}, {"question_ua": "До котрої можна забрати дітей?", "options": ["До 17:00", "До 13:00", "До 14:30"], "answer": "До 17:00"}]'::jsonb, 32, 1.000, 49, 'PUBLISHED', 'claude_reading_a1_v3')
