values ('RD-A1-050', 'A1', 'notice', 'basics', 12, 'Список приладдя для 1 класу', 'Popis pribora za 1. razred',
        'POPIS PRIBORA – 1. RAZRED
Školska torba, pernica, dvije olovke, gumica, šiljilo, ravnalo, bojice, vodene boje, škare i omot za knjige.
Udžbenike i radne bilježnice kupite u trgovini.
Na sve stvari napišite ime djeteta.
Razrednica',
        'СПИСОК ПРИЛАДДЯ — 1 КЛАС
Шкільний рюкзак, пенал, два олівці, гумка, стругачка, лінійка, кольорові олівці, акварельні фарби, ножиці й обкладинка для книжок.
Підручники й робочі зошити купіть у магазині.
На всіх речах напишіть ім’я дитини.
Класна керівниця',
        '[{"form": "popis", "lemma": "popis pribora", "ua": "список приладдя", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «popis pribora»"}, {"form": "pribora", "lemma": "popis pribora", "ua": "список приладдя", "lesson": true, "pos": "сталий вираз", "gram": "родовий відмінок (кого? чого?), однина. Частина виразу «popis pribora»"}, {"form": "razred", "lemma": "razred", "ua": "клас (у школі)", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "školska", "lemma": "školska torba", "ua": "шкільний рюкзак", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «školska torba»"}, {"form": "torba", "lemma": "školska torba", "ua": "шкільний рюкзак", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «školska torba»"}, {"form": "pernica", "lemma": "pernica", "ua": "пенал", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "dvije", "lemma": "dva", "ua": "два", "lesson": true, "pos": "числівник «два» (dvije — для ж. р.); після нього іменник у формі як родовий однини", "gram": "форма для ж. р.: «dvije jakne»"}, {"form": "olovke", "lemma": "olovka", "ua": "олівець", "lesson": true, "pos": "іменник, жіночий рід", "gram": "форма після 2, 3, 4 (як родовий однини)"}, {"form": "gumica", "lemma": "gumica", "ua": "гумка (для стирання)", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "šiljilo", "lemma": "šiljilo", "ua": "чинка (точилка)", "lesson": true, "pos": "іменник, середній рід"}, {"form": "ravnalo", "lemma": "ravnalo", "ua": "лінійка", "lesson": true, "pos": "іменник, середній рід"}, {"form": "bojice", "lemma": "bojice", "ua": "кольорові олівці", "lesson": true, "pos": "іменник, ж. р., лише множина"}, {"form": "vodene", "lemma": "vodene boje", "ua": "акварельні фарби", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «vodene boje»"}, {"form": "boje", "lemma": "vodene boje", "ua": "акварельні фарби", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «vodene boje»"}, {"form": "škare", "lemma": "škare", "ua": "ножиці", "lesson": true, "pos": "іменник, ж. р., лише множина"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "omot", "lemma": "omot za knjige", "ua": "обгортка для книжок", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «omot za knjige»"}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false, "pos": "прийменник: + знахідний — для, за («za strance» — для іноземців)"}, {"form": "knjige", "lemma": "omot za knjige", "ua": "обгортка для книжок", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), множина. Частина виразу «omot za knjige»"}, {"form": "udžbenike", "lemma": "udžbenik", "ua": "підручник", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "знахідний відмінок (кого? що?), множина"}, {"form": "radne", "lemma": "radna bilježnica", "ua": "робочий зошит", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), множина. Частина виразу «radna bilježnica»"}, {"form": "bilježnice", "lemma": "radna bilježnica", "ua": "робочий зошит", "lesson": true, "pos": "сталий вираз", "gram": "знахідний відмінок (кого? що?), множина. Частина виразу «radna bilježnica»"}, {"form": "kupite", "lemma": "kupiti", "ua": "купити", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "trgovini", "lemma": "trgovina", "ua": "магазин / крамниця", "lesson": true, "pos": "іменник, жіночий рід", "gram": "місцевий відмінок (де? про кого? про що?), однина"}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false, "pos": "прийменник: + знахідний — куди? («na posao»), + місцевий — де? («na poslu»)"}, {"form": "sve", "lemma": "sve", "ua": "все; усе", "lesson": true, "pos": "займенник «все»; «sve više» — дедалі більше"}, {"form": "stvari", "lemm