        '[{"question_ua": "Скільки олівців потрібно?", "options": ["Два", "Один", "П’ять"], "answer": "Два"}, {"question_ua": "Де купити підручники?", "options": ["У магазині", "У школі", "В інтернеті"], "answer": "У магазині"}, {"question_ua": "Що треба написати на речах?", "options": ["Ім’я дитини", "Номер класу", "Адресу"], "answer": "Ім’я дитини"}]'::jsonb, 33, 0.970, 50, 'PUBLISHED', 'claude_reading_a1_v3')
