values ('RD-A1-052', 'A1', 'instruction', 'health', 12, 'Що робити під час землетрусу', 'Što raditi kod potresa',
        'ŠTO RADITI KOD POTRESA?
Ostanite mirni.
Idite pod stol i čekajte kraj potresa.
Ne idite u lift.
Poslije potresa izađite iz zgrade.
Za pomoć zovite 112 – hitna služba radi 24 sata.',
        'ЩО РОБИТИ ПІД ЧАС ЗЕМЛЕТРУСУ?
Зберігайте спокій.
Сховайтеся під стіл і чекайте кінця землетрусу.
Не заходьте в ліфт.
Після землетрусу вийдіть із будівлі.
По допомогу дзвоніть 112 — екстрена служба працює цілодобово.',
        '[{"form": "što", "lemma": "što", "ua": "що", "lesson": true, "pos": "займенник «що»; як сполучник — «що» («Hvala što …»)"}, {"form": "raditi", "lemma": "raditi", "ua": "працювати, робити", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)"}, {"form": "kod", "lemma": "kod", "ua": "у; біля; в (когось)", "lesson": false, "pos": "прийменник + родовий відмінок («kod kuće» — вдома, «kod liječnika» — у лікаря)"}, {"form": "potresa", "lemma": "potres", "ua": "землетрус", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "ostanite", "lemma": "ostati", "ua": "залишитися", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "mirni", "lemma": "miran", "ua": "спокійний", "lesson": true, "pos": "прикметник", "gram": "називний відмінок (хто? що?), множина, ч. р."}, {"form": "idite", "lemma": "ići", "ua": "іти, їхати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "наказовий спосіб: ви (зробіть!). «ne idite» — не йдіть"}, {"form": "pod", "lemma": "pod", "ua": "підлога", "lesson": true, "pos": "іменник, ч. р. «підлога» (також прийменник «під»)"}, {"form": "stol", "lemma": "stol", "ua": "стіл", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false, "pos": "сполучник"}, {"form": "čekajte", "lemma": "čekati", "ua": "чекати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "kraj", "lemma": "kraj", "ua": "кінець; край, місцевість", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "ne", "lemma": "ne", "ua": "ні", "lesson": true, "pos": "частка"}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false, "pos": "прийменник: + знахідний — куди? («u školu»), + місцевий — де? («u Zagrebu»)"}, {"form": "lift", "lemma": "lift", "ua": "ліфт", "lesson": true, "pos": "іменник, чоловічий рід"}, {"form": "poslije", "lemma": "poslije", "ua": "після", "lesson": true, "pos": "прийменник + родовий («poslije posla»); прислівник «потім»"}, {"form": "izađite", "lemma": "izaći", "ua": "вийти", "lesson": true, "pos": "дієслово, доконаний вид (що зробити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "iz", "lemma": "iz", "ua": "з (звідки)", "lesson": true, "pos": "прийменник + родовий відмінок"}, {"form": "zgrade", "lemma": "zgrada", "ua": "будівля", "lesson": true, "pos": "іменник, жіночий рід", "gram": "родовий відмінок (кого? чого?), однина"}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false, "pos": "прийменник: + знахідний — для, за («za strance» — для іноземців)"}, {"form": "pomoć", "lemma": "pomoć", "ua": "допомога", "lesson": true, "pos": "іменник, жіночий рід"}, {"form": "zovite", "lemma": "zvati", "ua": "дзвонити; кликати", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "наказовий спосіб: ви (зробіть!)"}, {"form": "hitna", "lemma": "hitna služba", "ua": "екстрена служба", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «hitna služba»"}, {"form": "služba", "lemma": "hitna služba", "ua": "екстрена служба", "lesson": true, "pos": "сталий вираз", "gram": "частина виразу «hitna služba»"}, {"form": "radi", "lemma": "raditi", "ua": "працювати, робити", "lesson": true, "pos": "дієслово, недоконаний вид (що робити?)", "gram": "теперішній час: він / вона / воно"}, {"form": "sata", "lemma": "sat", "ua": "годинник / година", "lesson": true, "pos": "іменник, чоловічий рід", "gram": "родовий відмінок (кого? чого?), однина. Після 2, 3, 4 і «pola»: «dva sata», «pola sata»"}]'::jsonb,
        '[{"question_ua": "Куди треба сховатися під час землетрусу?", "options": ["Під стіл", "У ліфт", "На балкон"], "answer": "Під стіл"}, {"question_ua": "Що зробити після землетрусу?", "options": ["Вийти з будівлі", "Залишитися в ліфті", "Лягти спати"], "answer": "Вийти з будівлі"}, {"question_ua": "Який номер екстреної служби?", "options": ["112", "1313", "01 456 7890"], "answer": "112"}]'::jsonb, 29, 1.000, 52, 'PUBLISHED', 'claude_reading_a1_v3')
on conflict (code) do nothing;

-- Журнал перевірки (один запис на текст)
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'reading_text', r.id, null, r.status, 'auto_passed', 'ai', '[]'::jsonb, 'reading_a1_v3 2026-11-04: тексти для модулів A1.7, A1.11, A1.12 (аудит A0 / A1). Бета, як уроки A1; потрібна перевірка носієм.'
from public.reading_texts r
where r.code in ('RD-A1-041', 'RD-A1-042', 'RD-A1-043', 'RD-A1-044', 'RD-A1-045', 'RD-A1-046', 'RD-A1-047', 'RD-A1-048', 'RD-A1-049', 'RD-A1-050', 'RD-A1-051', 'RD-A1-052')
  and not exists (select 1 from public.content_reviews c where c.entity_id = r.id and c.notes = 'reading_a1_v3 2026-11-04: тексти для модулів A1.7, A1.11, A1.12 (аудит A0 / A1). Бета, як уроки A1; потрібна перевірка носієм.');

-- Самоперевірка: якщо щось не так — усе відкочується
do $$
declare v_total int; v_bad int;
begin
  select count(*) into v_total from public.reading_texts
   where code in ('RD-A1-041', 'RD-A1-042', 'RD-A1-043', 'RD-A1-044', 'RD-A1-045', 'RD-A1-046', 'RD-A1-047', 'RD-A1-048', 'RD-A1-049', 'RD-A1-050', 'RD-A1-051', 'RD-A1-052') and cefr = 'A1' and status = 'PUBLISHED' and module_order in (7, 11, 12);
  select count(*) into v_bad from public.reading_texts r where r.code in ('RD-A1-041', 'RD-A1-042', 'RD-A1-043', 'RD-A1-044', 'RD-A1-045', 'RD-A1-046', 'RD-A1-047', 'RD-A1-048', 'RD-A1-049', 'RD-A1-050', 'RD-A1-051', 'RD-A1-052')
     and (jsonb_array_length(r.questions) <> 3 or r.known_ratio < 0.9
          or exists (select 1 from jsonb_array_elements(r.glossary) e
                     where e->>'pos' is null or (e->>'gram' is null and e->>'form' <> lower(e->>'lemma'))));
  if v_total <> 12 then raise exception 'Нових текстів A1 %, очікувалось 12 (код уже зайнятий іншим текстом?)', v_total; end if;
  if v_bad > 0 then raise exception '% текстів без питань, словничка чи граматичних підказок', v_bad; end if;
  raise notice 'Готово: нових текстів A1 (модулі 7, 11, 12) — %', v_total;
end $$;

commit;
